import{z as d,x as i,o as s,c as p,q as o,j as t,D as r,d as E,s as n,S as B,b as e}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"最大流 Ford–Fulkerson","description":"","frontmatter":{"title":"最大流 Ford–Fulkerson","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/max-flow-ff.md","filePath":"cs/max-flow-ff.md","lastUpdated":1791413859000}'),f={name:"cs/max-flow-ff.md"};function A(F,a,m,u,h,C){const l=i("Mermaid");return s(),p("div",null,[a[2]||(a[2]=o('<h1 id="最大流-ford–fulkerson" tabindex="-1">最大流 Ford–Fulkerson <a class="header-anchor" href="#最大流-ford–fulkerson" aria-label="Permalink to &quot;最大流 Ford–Fulkerson&quot;">​</a></h1><div class="epigraph"><p>源到汇的最大流量等于最小割的容量；沿残量网络增广，直到没有 $s$–$t$ 路。</p><footer>—— 据 Ford and Fulkerson, Maximal Flow Through a Network, 1956；CLRS 第 26 章整理</footer></div><p>上一课<a href="/cs/mst-kruskal-prim">Kruskal 与 Prim</a>处理无向边权之和。流网络是有向边、容量、源 \\(s\\) 与汇 \\(t\\)。本课不重做生成树。缺口是：合法流（容量约束、守恒）的最大值，以及用残量路上的增广来算。本课只钉 Ford–Fulkerson 方法与最大流最小割。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>流 \\(f\\) 满足 \\(0\\le f(e)\\le c(e)\\)，除 \\(s,t\\) 外流入等于流出。值 \\(|f|\\) 为 \\(s\\) 净流出。残量图：正向剩余 \\(c-f\\)，反向 \\(f\\)（可退流）。若残量里有 \\(s\\)–\\(t\\) 路，沿路加 \\(\\Delta\\) 仍合法且值增大。没有残量路时，\\(s\\) 侧可达集给出最小割，容量等于 \\(|f|\\)。</p><p><span class="marginnote">术语翻译：残量图是「还剩多少可通行」的账本——每条正向边记「这条管道还能再灌 \\(c-f\\)」，每条反向边记「已经灌进去的 \\(f\\) 可以反悔抽回」。增广走反向边就是把旧流量改道，不是凭空多出管道。</span></p><p>缺口不是线性规划，而是这条组合算法。整数容量时若每次 \\(\\Delta\\ge 1\\)，有限步终止；病态选择可使增广次数随容量指数，Edmonds–Karp 用 BFS 最短增广把迭代变成 \\(O(VE^2)\\)。</p><h3 id="方法不是单一实现" tabindex="-1">方法不是单一实现 <a class="header-anchor" href="#方法不是单一实现" aria-label="Permalink to &quot;方法不是单一实现&quot;">​</a></h3><p>Ford–Fulkerson 是「只要有增广路就增」的框架。最短路增广（Edmonds–Karp）或 Dinic 分层是后继实现。本课证明框架正确 + 最大流 = 最小割；实现默认用 BFS 找路，接上<a href="/cs/bfs-unweighted">无权 BFS</a>。</p><p><span class="marginnote">Ford–Fulkerson 1956。割是顶点划分，容量是前向边容量和。反向边在残量里出现，不是原图多出来的物理管道。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>\\(f\\leftarrow 0\\)。循环：在残量上找 \\(s\\)–\\(t\\) 路，算瓶颈 \\(\\Delta\\)，更新 \\(f\\) 与残量。无可增广路则停。割 \\((S,T)\\)：\\(S\\) 为残量中 \\(s\\) 可达。</p>',12)),(s(),t(B,null,{default:r(()=>[n(l,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E6%B5%81%20f%22%5D%20--%3E%20Gf%5B%22%E6%AE%8B%E9%87%8F%E7%BD%91%E7%BB%9C%22%5D%0A%20%20Gf%20--%3E%20P%5B%22s%E2%80%93t%20%E5%A2%9E%E5%B9%BF%E8%B7%AF%EF%BC%9F%22%5D%0A%20%20P%20--%3E%7C%22%E6%9C%89%22%7C%20AUG%5B%22%E6%B2%BF%E8%B7%AF%E5%8A%A0%20%CE%94%22%5D%0A%20%20AUG%20--%3E%20F%0A%20%20P%20--%3E%7C%22%E6%97%A0%22%7C%20MIN%5B%22S%3D%E5%8F%AF%E8%BE%BE%E9%9B%86%EF%BC%8C%E6%9C%80%E5%B0%8F%E5%89%B2%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"有理容量有限终止；无理容量可无限，主干用整数。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"守恒使任意割的净流等于 \\(|f|\\)，故 \\(|f|\\le\\) 任何割容量。增广结束时 \\(|f|\\) 达到某割，故最大。二分图匹配可化成单位容量网络，本课点名：最大匹配 = 最大流，不写匈牙利。",-1)),a[6]||(a[6]=e("p",null,"算法停机那一刻，为什么流值恰好卡在最小割上，可以把论证链摆出来：",-1)),(s(),t(B,null,{default:r(()=>[n(l,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20STOP%5B%22%E5%81%9C%E6%9C%BA%EF%BC%9A%E6%AE%8B%E9%87%8F%E6%97%A0%20s%E2%80%93t%20%E8%B7%AF%22%5D%20--%3E%20REACH%5B%22S%20%E5%8F%96%E6%AE%8B%E9%87%8F%E4%B8%AD%20s%20%E5%8F%AF%E8%BE%BE%E9%9B%86%22%5D%0A%20%20REACH%20--%3E%20SAT%5B%22%E8%B7%A8%E5%89%B2%E7%9A%84%E8%BE%B9%E5%85%A8%E6%BB%A1%E6%B5%81%22%5D%0A%20%20SAT%20--%3E%20EQ%5B%22%E6%AD%A4%E5%89%B2%E5%AE%B9%E9%87%8F%E6%81%B0%E7%AD%89%E4%BA%8E%E6%B5%81%E5%80%BC%22%5D%0A%20%20BND%5B%22%E4%BB%BB%E4%BD%95%E6%B5%81%E5%80%BC%20%E2%89%A4%20%E4%BB%BB%E4%BD%95%E5%89%B2%E5%AE%B9%E9%87%8F%22%5D%20--%3E%20CONC%5B%22%E6%95%85%E6%AD%A4%E6%B5%81%E6%9C%80%E5%A4%A7%E3%80%81%E6%AD%A4%E5%89%B2%E6%9C%80%E5%B0%8F%22%5D%0A%20%20EQ%20--%3E%20CONC%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=o('<p><span class="marginnote">数字实例：\\(s\\) 到 \\(t\\) 有两条并联管道，容量分别为 3 与 2，最大流就是 \\(3+2=5\\)；把 \\(s\\) 的两条出边割断，「割容量」也恰是 5。任何流都不可能穿过比总截面更大的量——这就是最大流必然撞上某个最小割的原因。</span></p><p>不要把 MST 的割与流的割混名：一个选边权最小连通，一个是容量之和最小的 \\(s\\)–\\(t\\) 划分。</p><p><span class="marginnote">常见误区：图论里有两个都叫「割」的东西。MST 的割问「跨过划分的边里哪条最轻」，服务生成树；流网络的割问「跨过划分的容量总和最少是多少」，给最大流当上界。对象不同、最值不同，结论不要互相串用。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写费用流、不写推送重标。多源多汇加超级源汇即可。容量随输入指数时要小心增广次数；Edmonds–Karp 给出多项式。后课离开图，进入串匹配。</p><p>后课默认：最大流 = 反复增广；最大流最小割；整数容量 + 最短增广多项式。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>残量增广直到无 \\(s\\)–\\(t\\) 路；此时流最大、割最小。</li><li>框架叫 Ford–Fulkerson；BFS 增广即 Edmonds–Karp。</li><li>整数容量保证终止。</li><li>出处：Ford and Fulkerson, 1956；CLRS 第 26 章。</li></ul>',8))])}const k=d(f,[["render",A]]);export{c as __pageData,k as default};
